CREATE TABLE IF NOT EXISTS digital_role_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,role_name TEXT NOT NULL,owner_agent_key TEXT NOT NULL,manager_role TEXT NOT NULL,status TEXT NOT NULL,source_reference TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,role_key));
CREATE TABLE IF NOT EXISTS digital_role_tasks(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,task_key TEXT NOT NULL,task_name TEXT NOT NULL,category TEXT NOT NULL,execution_class TEXT NOT NULL CHECK(execution_class IN('DIGITAL','PHYSICAL','LEGALLY_RESERVED')),tool_key TEXT NOT NULL,approval_policy_json TEXT NOT NULL,required_evidence_json TEXT NOT NULL,postcondition_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,role_key,task_key));
CREATE TABLE IF NOT EXISTS digital_role_executions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,task_key TEXT NOT NULL,source_record_type TEXT NOT NULL,source_record_id TEXT NOT NULL,plan_json TEXT NOT NULL,input_json TEXT NOT NULL,receipt_json TEXT NOT NULL,outcome_json TEXT NOT NULL,confidence REAL,postcondition_json TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,initiated_by TEXT NOT NULL,idempotency_key TEXT NOT NULL,UNIQUE(organization_id,property_id,idempotency_key));
CREATE TABLE IF NOT EXISTS digital_role_handoffs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,execution_id TEXT NOT NULL,exception_type TEXT NOT NULL CHECK(exception_type IN('PHYSICAL','LEGALLY_RESERVED')),title TEXT NOT NULL,instructions TEXT NOT NULL,assigned_role TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE IF NOT EXISTS digital_role_reports(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,report_type TEXT NOT NULL CHECK(report_type IN('ON_DEMAND','SHIFT_END','DAILY','WEEKLY','ROLLUP')),period_start TEXT NOT NULL,period_end TEXT NOT NULL,summary_text TEXT NOT NULL,structured_json TEXT NOT NULL,source_links_json TEXT NOT NULL,status TEXT NOT NULL,generated_by TEXT NOT NULL,generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS digital_role_report_schedules(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,cadence TEXT NOT NULL CHECK(cadence IN('SHIFT_END','DAILY','WEEKLY')),delivery_target TEXT NOT NULL,hierarchy_rollup INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL,next_run_at TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,role_key,cadence));
CREATE TABLE IF NOT EXISTS digital_role_evaluations(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,role_key TEXT NOT NULL,task_key TEXT NOT NULL,total_cases INTEGER NOT NULL CHECK(total_cases>=20),passed_cases INTEGER NOT NULL,false_approval_count INTEGER NOT NULL,false_escalation_count INTEGER NOT NULL,out_of_policy_count INTEGER NOT NULL CHECK(out_of_policy_count=0),evidence_json TEXT NOT NULL,executed_at TEXT NOT NULL,UNIQUE(organization_id,property_id,role_key,task_key));
CREATE TABLE IF NOT EXISTS digital_role_evaluation_cases(id TEXT PRIMARY KEY,evaluation_id TEXT NOT NULL,case_number INTEGER NOT NULL,input_json TEXT NOT NULL,expected_outcome TEXT NOT NULL,actual_outcome TEXT NOT NULL,status TEXT NOT NULL,policy_evidence_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(evaluation_id,case_number));
CREATE INDEX IF NOT EXISTS digital_role_task_scope_idx ON digital_role_tasks(organization_id,property_id,role_key,status);
CREATE INDEX IF NOT EXISTS digital_role_execution_scope_idx ON digital_role_executions(organization_id,property_id,role_key,completed_at);
CREATE INDEX IF NOT EXISTS digital_role_report_scope_idx ON digital_role_reports(organization_id,property_id,role_key,generated_at);
